"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { motion } from "framer-motion";
import { useChat, type UIMessage, type FileUIPart } from "@ai-sdk/react";
import {
	InputMessage,
	type QueuedMessage,
} from "@aevryn/ui/components/ui/input-message";
import { Button } from "@aevryn/ui/components/ui/button";
import { Tooltip } from "@aevryn/ui/components/ui/tooltip";
import {
	QueuedStack,
	collapsedStackHeight,
	useQueueCardHeight,
} from "@aevryn/ui/components/queued-stack";
import { useIcon } from "@aevryn/ui/lib/icon-context";
import { useShape } from "@aevryn/ui/lib/shape-context";
import { spring } from "@aevryn/ui/lib/springs";
import { cn } from "@aevryn/ui/lib/utils";
import { Slider } from "@aevryn/ui/components/ui/slider";
import {
	DropdownMenu,
	DropdownTrigger,
	DropdownContent,
} from "@aevryn/ui/components/ui/dropdown";

const SUGGESTIONS = [
	"Monitor this product and notify me when its price drops below ₹5,000",
	"Scrape these internship listings every week and summarize new ones",
	"Fill out this job application form for me",
	"Wake me up daily at 8 AM with a summary of my pending workflows",
];

// Token quality slider: steps 1–5 → maxOutputTokens for the chat request.
const TOKEN_STEPS = [1024, 2048, 4096, 8192, 16384] as const;

function formatTokens(n: number): string {
	return n >= 1024 ? `${Math.round(n / 1024)}K` : `${n}`;
}

function messageText(m: UIMessage): string {
	const parts = m.parts ?? [];
	const text: string[] = [];
	for (const part of parts) {
		if (part.type === "text") {
			text.push("text" in part ? part.text : "");
		}
	}
	return text.join("");
}

function fileToDataUrl(file: File): Promise<string> {
	return new Promise((resolve, reject) => {
		const reader = new FileReader();
		reader.onload = () => resolve(String(reader.result));
		reader.onerror = () => reject(reader.error);
		reader.readAsDataURL(file);
	});
}

interface ChatComposerProps {
	/** Thread this chat belongs to. Omit to let /api/chat create one. */
	threadId?: string;
}

export function ChatComposer({ threadId }: ChatComposerProps) {
	const shape = useShape();
	const PlusIcon = useIcon("plus");
	const ChevronDownIcon = useIcon("chevron-down");
	const cardH = useQueueCardHeight();
	const [value, setValue] = useState("");
	const [files, setFiles] = useState<File[]>([]);
	const [queue, setQueue] = useState<QueuedMessage[]>([]);
	const [tokenStep, setTokenStep] = useState<number>(3);

	const { messages, sendMessage, stop, status } = useChat({
		api: "/api/chat",
		id: threadId,
		body: { threadId },
	});

	const isStreaming = status === "submitted" || status === "streaming";

	// The message currently morphing from its queue card into a settled bubble.
	// `messageId` is the streaming message id; `queueId` keeps the shared
	// layoutId alive so framer can animate card → bubble in one movement.
	const [morph, setMorph] = useState<{
		messageId: string;
		queueId: string;
	} | null>(null);
	const pendingMorphRef = useRef<{ queueId: string; text: string } | null>(
		null,
	);
	const morphTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
	useEffect(
		() => () => {
			if (morphTimerRef.current) clearTimeout(morphTimerRef.current);
		},
		[],
	);
	useEffect(() => {
		const pending = pendingMorphRef.current;
		if (!pending || morph) return;
		const last = messages[messages.length - 1];
		if (last?.role === "user" && messageText(last) === pending.text) {
			setMorph({ messageId: last.id, queueId: pending.queueId });
			pendingMorphRef.current = null;
			if (morphTimerRef.current) clearTimeout(morphTimerRef.current);
			morphTimerRef.current = setTimeout(() => setMorph(null), 450);
		}
	}, [messages, morph]);

	const history = useMemo(
		() =>
			messages
				.filter((m) => m.role === "user")
				.map(messageText)
				.filter(Boolean),
		[messages],
	);

	// Float the composer over the transcript: measure it to reserve scroll
	// padding (plus the collapsed queue stack) and to position the stack, and
	// keep the transcript pinned to the latest message.
	const inputRef = useRef<HTMLDivElement>(null);
	const [inputH, setInputH] = useState(0);
	useEffect(() => {
		const el = inputRef.current;
		if (!el) return;
		const ro = new ResizeObserver(() => setInputH(el.offsetHeight));
		ro.observe(el);
		setInputH(el.offsetHeight);
		return () => ro.disconnect();
	}, []);

	const scrollRef = useRef<HTMLDivElement>(null);
	useEffect(() => {
		const el = scrollRef.current;
		if (el) el.scrollTop = el.scrollHeight;
	}, [messages, inputH, queue]);

	// Double-click a queued card (or its ✎) to pull it back into the composer.
	const editQueued = (item: QueuedMessage) => {
		setValue(item.text);
		setFiles(item.files);
		setQueue((q) => q.filter((x) => x.id !== item.id));
		requestAnimationFrame(() => {
			const el = inputRef.current?.querySelector("textarea");
			if (el) {
				el.focus();
				el.setSelectionRange(el.value.length, el.value.length);
			}
		});
	};

	const handleSend = async (
		text: string,
		sent: File[],
		meta?: { queuedId?: string },
	) => {
		const fileParts: FileUIPart[] = [];
		for (const file of sent ?? []) {
			fileParts.push({
				type: "file",
				mediaType: file.type,
				filename: file.name,
				url: await fileToDataUrl(file),
			});
		}

		if (meta?.queuedId) {
			pendingMorphRef.current = { queueId: meta.queuedId, text };
		}

		await sendMessage(
			{ text, files: fileParts.length > 0 ? fileParts : undefined },
			{ body: { maxOutputTokens: TOKEN_STEPS[tokenStep - 1] } },
		);

		// Only clear the composer for an actual user submit — a queued
		// dispatch must leave any in-progress draft untouched.
		if (!meta?.queuedId) {
			setValue("");
			setFiles([]);
		}
	};

	// Height of the collapsed queue pile — reserved under the transcript
	// alongside the composer.
	const collapsedStackH = collapsedStackHeight(queue.length, cardH);

	return (
		<div
			className="relative w-full self-stretch"
			style={{ height: Math.max(inputH, 56) }}
		>
			<div
				ref={scrollRef}
				className="absolute inset-0 overflow-y-auto scrollbar-hide"
			>
				<div
					className="flex min-h-full flex-col justify-start gap-2"
					style={{
						paddingBottom:
							inputH + 8 + (queue.length > 0 ? collapsedStackH + 8 : 0),
					}}
				>
					{messages.map((m) => {
						const text = messageText(m);
						const isMorphing = morph?.messageId === m.id;
						if (m.role === "user") {
							return isMorphing ? (
								<motion.div
									key={m.id}
									layoutId={`qm-${morph.queueId}`}
									layout
									initial={false}
									transition={spring.moderate}
									style={{ transformOrigin: "bottom right" }}
									className={cn(
										"max-w-[80%] self-end whitespace-pre-wrap break-words px-3.5 py-2 text-[14px] text-pretty bg-[color-mix(in_oklab,var(--accent),var(--background)_45%)] text-accent-foreground",
										shape.bg,
									)}
								>
									<motion.span layout className="inline-block align-top">
										{text}
									</motion.span>
								</motion.div>
							) : (
								<div
									key={m.id}
									className={cn(
										"max-w-[80%] self-end whitespace-pre-wrap break-words px-3.5 py-2 text-[14px] text-pretty bg-[color-mix(in_oklab,var(--accent),var(--background)_45%)] text-accent-foreground",
										shape.bg,
									)}
								>
									{text}
								</div>
							);
						}
						return (
							<div
								key={m.id}
								className="max-w-[80%] self-start whitespace-pre-wrap break-words py-2 text-[14px] text-foreground"
							>
								{text}
							</div>
						);
					})}
				</div>
			</div>

			{/* Queued messages — Sonner-style stack floated just above the
          composer (front card = next to dispatch). */}
			<QueuedStack
				queue={queue}
				onQueueChange={setQueue}
				onEdit={editQueued}
				onRemove={(item) => setQueue((q) => q.filter((x) => x.id !== item.id))}
				bottom={inputH + 8}
				morphLayoutId={(item) => `qm-${item.id}`}
			/>

			<InputMessage
				ref={inputRef}
				className="absolute inset-x-0 bottom-0 bg-background/45"
				value={value}
				onValueChange={setValue}
				onSend={handleSend}
				placeholderSuggestion="Why is every other input box so stiff?"
				suggestions={SUGGESTIONS}
				// ArrowUp recalls sent messages, ArrowDown walks back to the draft.
				history={history}
				files={files}
				onFilesChange={setFiles}
				leftSlot={({ openFilePicker }) => (
					<Tooltip content="Attach" side="top">
						<Button
							variant="ghost"
							size="icon-sm"
							aria-label="Attach files"
							disabled
							onClick={() => openFilePicker()}
						>
							<PlusIcon />
						</Button>
					</Tooltip>
				)}
				rightSlot={
					<DropdownMenu>
						<DropdownTrigger
							render={
								<Button variant="ghost" size="sm" trailingIcon={ChevronDownIcon}>
									{formatTokens(TOKEN_STEPS[tokenStep - 1])}
								</Button>
							}
						/>
						<DropdownContent>
							<Slider
								label="Output tokens"
								className="p-4"
								value={tokenStep}
								onChange={(v) =>
									setTokenStep(Array.isArray(v) ? v[0] : v)
								}
								min={1}
								max={5}
								step={1}
								formatValue={(v) =>
									formatTokens(
										TOKEN_STEPS[
											Math.min(Math.max(Math.round(v), 1), 5) - 1
										] ?? v,
									)
								}
							/>
						</DropdownContent>
					</DropdownMenu>
				}
				// While streaming, submits enqueue; flipping back to idle
				// dispatches the head of the queue through onSend.
				status={isStreaming ? "streaming" : "idle"}
				queue={queue}
				onQueueChange={setQueue}
				onStop={() => {
					void stop();
				}}
				// The built-in queue rows are replaced by the stacked cards above.
				showQueue={false}
			/>
		</div>
	);
}

