const chatBodySchema = z.object({
	threadId: z.string().min(1).optional(),
	workspaceId: z.string().min(1).optional(),
	message: z.string().min(1).max(20_000).optional(),
	autoApprove: z.boolean().optional(),
	maxOutputTokens: z.number().int().min(64).max(32_768).optional(),
	attachments: z
		.array(
			z.object({
				id: z.string().min(1),
				url: z.string().min(1),
				mimeType: z.string().min(1),
			}),
		)
		.max(8)
		.optional(),
	// useChat sends the full UIMessage history; the last user message is the
	// new prompt. Kept loose on purpose — the shape mirrors UIMessage parts.
	messages: z
		.array(
			z.object({
				id: z.string().optional(),
				role: z.string(),
				content: z.array(z.unknown()),
			}),
		)
		.optional(),
});

// Extract the new prompt + attachments from a useChat message history.
function promptFromMessages(
	messages: z.output<typeof chatBodySchema>["messages"],
): { message: string; attachments?: z.output<typeof chatBodySchema>["attachments"] } {
	const last = [...(messages ?? [])].reverse().find((m) => m.role === "user");
	if (!last) return { message: "" };
	const text = (last.content as Array<{ type?: string; text?: string }>)
		.filter((p) => p?.type === "text")
		.map((p) => p.text ?? "")
		.join("")
		.trim();
	const attachments = (last.content as Array<{
		type?: string;
		url?: string;
		mimeType?: string;
		filename?: string;
	}>)
		.filter((p) => p?.type === "file")
		.map((p) => ({
			id: p.filename ?? "file",
			url: p.url ?? "",
			mimeType: p.mimeType ?? "application/octet-stream",
		}));
	return { message: text, attachments: attachments.length > 0 ? attachments : undefined };
}

