"use client";

import type { ReactNode } from "react";
import { ChatMessage as UiChatMessage } from "@aevryn/ui/components/ui/chat-message";

/** A single chat message part (mirrors UIMessage parts / DB content JSONB). */
export interface ChatMessagePart {
  type: string;
  text?: string;
  toolName?: string;
  [key: string]: unknown;
}

export interface ChatMessageProps {
  message: {
    id: string;
    role: "user" | "assistant";
    parts: ChatMessagePart[];
  };
  /** Timestamp shown in the hover-revealed meta row (user messages only). */
  time?: ReactNode;
  /** Optional extra content rendered in the bubble below the streamed text
   *  (e.g. a ThinkingIndicator while the durable run is active). */
  children?: ReactNode;
}

function messageText(parts: ChatMessagePart[]): string {
  return parts
    .filter((p) => p.type === "text")
    .map((p) => p.text ?? "")
    .join("");
}

/** The tool-call shim for MVP: tool parts render as a muted inline note until
 *  richer tool UIs (ThinkingSteps etc.) land in Phase 3. */
function toolNote(parts: ChatMessagePart[]): string | null {
  const tools = [...new Set(parts.filter((p) => p.type.startsWith("tool-")).map((p) => p.toolName))];
  if (tools.length === 0) return null;
  return `Running: ${tools.join(", ")}`;
}

/** Renders one chat message from its parts. Text parts become the bubble body;
 *  tool-* parts collapse into a muted note for now. */
export function ChatMessage({ message, time, children }: ChatMessageProps) {
  const text = messageText(message.parts);
  const note = toolNote(message.parts);
  const body = text || note || children;

  if (body == null) return null;

  return (
    <UiChatMessage from={message.role === "assistant" ? "assistant" : "user"} time={time}>
      {body}
    </UiChatMessage>
  );
}

export default ChatMessage;

