	type SystemMessageProps as UiSystemMessageProps,
} from "@aevryn/ui/components/ui/system-message";

export interface SystemMessageProps
	extends Omit<UiSystemMessageProps, "children"> {
	/** Spacing before the next message — the old-workspace `mb-[40px]` pattern. */
	spaced?: boolean;
	children?: ReactNode;
}

/** Thin wrapper over the packages/ui SystemMessage that applies the
 *  conversation spacing convention (mb-[40px]) by default. */
export function SystemMessage({
	spaced = true,
	className,
	children,
	...props
}: SystemMessageProps) {
	return (
		<UiSystemMessage
			className={spaced ? `mb-[40px] ${className ?? ""}` : className}
			{...props}
		>
			{children}
