"use client";

import { useEffect, useRef } from "react";
import { supabaseClient } from "@/lib/supabase-client";
import { useThreadStore } from "@/stores/thread-store";
import { useNotificationsStore } from "@/stores/notifications-store";
import type { RealtimeChannel } from "@supabase/supabase-js";

interface MessageContentPart {
  type: string;
  text?: string;
  [key: string]: unknown;
}

interface ThreadActivity {
  id: string;
  type: string;
  status: string;
  title: string;
  stepLabel?: string;
  detail?: unknown;
}

interface UseRealtimeThreadOptions {
  threadId: string;
  /** Current logged-in user — subscribes to their cross-thread notifications. */
  userId?: string;
  /** A run_activity row was inserted for this thread. */
  onActivity?: (activity: ThreadActivity) => void;
  /** A run_activity row for this thread was updated (status/step changed). */
  onActivityUpdate?: (activity: ThreadActivity) => void;
  /** An approval request was created for this thread. */
  onApproval?: (approval: {
    id: string;
    runId: string;
    toolName: string;
    status: string;
  }) => void;
}

// run_id → thread_id cache, so the per-event lookup doesn't hit the DB on
// every activity insert/update.
const threadByRun = new Map<string, string>();

async function threadIdForRun(runId: string): Promise<string | null> {
  const cached = threadByRun.get(runId);
  if (cached !== undefined) return cached;
  const res = await supabaseClient
    .from("runs")
    .select("thread_id")
    .eq("id", runId)
    .maybeSingle();
  if (res.error || !res.data?.thread_id) return null;
  threadByRun.set(runId, res.data.thread_id);
  return res.data.thread_id;
}

function toActivity(newRow: {
  id: string;
  type: string;
  status: string;
  title: string;
  step_label?: string;
  detail?: unknown;
}): ThreadActivity {
  return {
    id: newRow.id,
    type: newRow.type,
    status: newRow.status,
    title: newRow.title,
    stepLabel: newRow.step_label,
    detail: newRow.detail,
  };
}

export function useRealtimeThread({
  threadId,
  userId,
  onActivity,
  onActivityUpdate,
  onApproval,
}: UseRealtimeThreadOptions) {
  const threadIdRef = useRef(threadId);
  const userIdRef = useRef(userId);
  const onActivityRef = useRef(onActivity);
  const onActivityUpdateRef = useRef(onActivityUpdate);
  const onApprovalRef = useRef(onApproval);

  useEffect(() => {
    threadIdRef.current = threadId;
    userIdRef.current = userId;
    onActivityRef.current = onActivity;
    onActivityUpdateRef.current = onActivityUpdate;
    onApprovalRef.current = onApproval;
  }, [threadId, userId, onActivity, onActivityUpdate, onApproval]);

  useEffect(() => {
    const sid = threadIdRef.current;
    if (!sid) return;

    // Thread-scoped room. `thread:{threadId}` hosts chat_messages,
    // run_activities and approval_requests.
    const channel = supabaseClient
      .channel(`thread:${sid}`)
      .on<{
        new: { id: string; role: string; content: unknown; status: string };
      }>(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "chat_messages",
          filter: `thread_id=eq.${sid}`,
        },
        (payload) => {
          const message = payload.new;
          if (!message) return;

          useThreadStore.getState().addMessage({
            id: message.id,
            role: message.role as "user" | "assistant",
            content: (message.content as MessageContentPart[]) || [],
            status: message.status,
          });
        },
      )
      .on<{
        new?: { id: string; status: string; content: unknown };
        old?: { id: string; status: string; content: unknown };
      }>(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "chat_messages",
          filter: `thread_id=eq.${sid}`,
        },
        (payload) => {
          const message = payload.new;
          const oldMessage = payload.old;
          if (!message || !oldMessage) return;

          if (message.status !== oldMessage.status) {
            useThreadStore.getState().updateMessage(message.id, {
              status: message.status,
            });
          }

          if (
            message.content &&
            JSON.stringify(message.content) !== JSON.stringify(oldMessage.content)
          ) {
            useThreadStore.getState().updateMessage(message.id, {
              content: message.content as MessageContentPart[],
            });
          }
        },
      )
      .on<{
        new: {
          id: string;
          type: string;
          status: string;
          title: string;
          run_id: string;
          step_label?: string;
          detail?: unknown;
        };
      }>(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "run_activities",
        },
        async (payload) => {
          const activity = payload.new;
          if (!activity) return;
          if ((await threadIdForRun(activity.run_id)) !== sid) return;

          onActivityRef.current?.(toActivity(activity));
        },
      )
      .on<{
        new: {
          id: string;
          type: string;
          status: string;
          title: string;
          run_id: string;
          step_label?: string;
          detail?: unknown;
        };
        old?: { id: string; status: string };
      }>(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "run_activities",
        },
        async (payload) => {
          const activity = payload.new;
          if (!activity) return;
          if ((await threadIdForRun(activity.run_id)) !== sid) return;

          onActivityUpdateRef.current?.(toActivity(activity));
        },
      )
      .on<{
        new: {
          id: string;
          run_id: string;
          tool_name: string;
          status: string;
        };
      }>(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "approval_requests",
        },
        async (payload) => {
          const approval = payload.new;
          if (!approval) return;
          if ((await threadIdForRun(approval.run_id)) !== sid) return;

          onApprovalRef.current?.({
            id: approval.id,
            runId: approval.run_id,
            toolName: approval.tool_name,
            status: approval.status,
          });
        },
      )
      .subscribe();

    // Cross-thread room: `user:{userId}` carries notifications for the bell.
    const uid = userIdRef.current;
    let notificationsChannel: RealtimeChannel | null = null;
    if (uid) {
      notificationsChannel = supabaseClient
        .channel(`user:${uid}`)
        .on<{
          new: {
            id: string;
            type: string;
            title: string;
            body: string;
            read_at: string | null;
          };
        }>(
          "postgres_changes",
          {
            event: "INSERT",
            schema: "public",
            table: "notifications",
            filter: `user_id=eq.${uid}`,
          },
          (payload) => {
            const n = payload.new;
            if (!n) return;
            useNotificationsStore.getState().addNotification({
              id: n.id,
              type: n.type,
              title: n.title,
              body: n.body,
              readAt: n.read_at,
            });
          },
        )
        .subscribe();
    }

    return () => {
      supabaseClient.removeChannel(channel);
      if (notificationsChannel) supabaseClient.removeChannel(notificationsChannel);
      threadByRun.clear();
    };
  }, []);
}

"use client";

import { useEffect, useRef } from "react";
import { supabaseClient } from "@/lib/supabase-client";
import { useThreadStore } from "@/stores/thread-store";
import { useNotificationsStore } from "@/stores/notifications-store";
import type { RealtimeChannel } from "@supabase/supabase-js";

interface MessageContentPart {
  type: string;
  text?: string;
  [key: string]: unknown;
}

interface ThreadActivity {
  id: string;
  type: string;
  status: string;
  title: string;
  stepLabel?: string;
  detail?: unknown;
}

interface UseRealtimeThreadOptions {
  threadId: string;
  /** Current logged-in user — subscribes to their cross-thread notifications. */
  userId?: string;
  /** A run_activity row was inserted for this thread. */
  onActivity?: (activity: ThreadActivity) => void;
  /** A run_activity row for this thread was updated (status/step changed). */
  onActivityUpdate?: (activity: ThreadActivity) => void;
  /** An approval request was created for this thread. */
  onApproval?: (approval: {
    id: string;
    runId: string;
    toolName: string;
    status: string;
  }) => void;
}

// run_id → thread_id cache, so the per-event lookup doesn't hit the DB on
// every activity insert/update.
const threadByRun = new Map<string, string>();

async function threadIdForRun(runId: string): Promise<string | null> {
  const cached = threadByRun.get(runId);
  if (cached !== undefined) return cached;
  const res = await supabaseClient
    .from("runs")
    .select("thread_id")
    .eq("id", runId)
    .maybeSingle();
  if (res.error || !res.data?.thread_id) return null;
  threadByRun.set(runId, res.data.thread_id);
  return res.data.thread_id;
}

function toActivity(newRow: {
  id: string;
  type: string;
  status: string;
  title: string;
  step_label?: string;
  detail?: unknown;
}): ThreadActivity {
  return {
    id: newRow.id,
    type: newRow.type,
    status: newRow.status,
    title: newRow.title,
    stepLabel: newRow.step_label,
    detail: newRow.detail,
  };
}

export function useRealtimeThread({
  threadId,
  userId,
  onActivity,
  onActivityUpdate,
  onApproval,
}: UseRealtimeThreadOptions) {
  const threadIdRef = useRef(threadId);
  const userIdRef = useRef(userId);
  const onActivityRef = useRef(onActivity);
  const onActivityUpdateRef = useRef(onActivityUpdate);
  const onApprovalRef = useRef(onApproval);

  useEffect(() => {
    threadIdRef.current = threadId;
    userIdRef.current = userId;
    onActivityRef.current = onActivity;
    onActivityUpdateRef.current = onActivityUpdate;
    onApprovalRef.current = onApproval;
  }, [threadId, userId, onActivity, onActivityUpdate, onApproval]);

  useEffect(() => {
    const sid = threadIdRef.current;
    if (!sid) return;

    // Thread-scoped room. `thread:{threadId}` hosts chat_messages,
    // run_activities and approval_requests.
    const channel = supabaseClient
      .channel(`thread:${sid}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "chat_messages",
          filter: `thread_id=eq.${sid}`,
        },
        (payload: {
          new: { id: string; role: string; content: unknown; status: string };
        }) => {
          const message = payload.new;
          if (!message) return;

          useThreadStore.getState().addMessage({
            id: message.id,
            role: message.role as "user" | "assistant",
            content: (message.content as MessageContentPart[]) || [],
            status: message.status,
          });
        },
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "chat_messages",
          filter: `thread_id=eq.${sid}`,
        },
        (
          payload: {
            new?: { id: string; status: string; content: unknown };
            old?: { id: string; status: string; content: unknown };
          },
        ) => {
          const message = payload.new;
          const oldMessage = payload.old;
          if (!message || !oldMessage) return;

          if (message.status !== oldMessage.status) {
            useThreadStore.getState().updateMessage(message.id, {
              status: message.status,
            });
          }

          if (
            message.content &&
            JSON.stringify(message.content) !== JSON.stringify(oldMessage.content)
          ) {
            useThreadStore.getState().updateMessage(message.id, {
              content: message.content as MessageContentPart[],
            });
          }
        },
      )
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "run_activities",
        },
        async (payload: {
          new: {
            id: string;
            type: string;
            status: string;
            title: string;
            run_id: string;
            step_label?: string;
            detail?: unknown;
          };
        }) => {
          const activity = payload.new;
          if (!activity) return;
          if ((await threadIdForRun(activity.run_id)) !== sid) return;

          onActivityRef.current?.(toActivity(activity));
        },
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "run_activities",
        },
        async (payload: {
          new: {
            id: string;
            type: string;
            status: string;
            title: string;
            run_id: string;
            step_label?: string;
            detail?: unknown;
          };
          old?: { id: string; status: string };
        }) => {
          const activity = payload.new;
          if (!activity) return;
          if ((await threadIdForRun(activity.run_id)) !== sid) return;

          onActivityUpdateRef.current?.(toActivity(activity));
        },
      )
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "approval_requests",
        },
        async (payload: {
          new: { id: string; run_id: string; tool_name: string; status: string };
        }) => {
          const approval = payload.new;
          if (!approval) return;
          if ((await threadIdForRun(approval.run_id)) !== sid) return;

          onApprovalRef.current?.({
            id: approval.id,
            runId: approval.run_id,
            toolName: approval.tool_name,
            status: approval.status,
          });
        },
      )
      .subscribe();

    // Cross-thread room: `user:{userId}` carries notifications for the bell.
    const uid = userIdRef.current;
    let notificationsChannel: RealtimeChannel | null = null;
    if (uid) {
      notificationsChannel = supabaseClient
        .channel(`user:${uid}`)
        .on(
          "postgres_changes",
          {
            event: "INSERT",
            schema: "public",
            table: "notifications",
            filter: `user_id=eq.${uid}`,
          },
          (payload: {
            new: {
              id: string;
              type: string;
              title: string;
              body: string;
              read_at: string | null;
            };
          }) => {
            const n = payload.new;
            if (!n) return;
            useNotificationsStore.getState().addNotification({
              id: n.id,
              type: n.type,
              title: n.title,
              body: n.body,
              readAt: n.read_at,
            });
          },
        )
        .subscribe();
    }

    return () => {
      supabaseClient.removeChannel(channel);
      if (notificationsChannel) supabaseClient.removeChannel(notificationsChannel);
      threadByRun.clear();
    };
  }, []);
}

