"use client";

import {
  DropdownMenu,
  DropdownTrigger,
  DropdownContent,
  DropdownSearch,
  DropdownLabel,
  DropdownEmpty,
} from "@aevryn/ui/components/ui/dropdown";

import { ChevronDown } from "lucide-react";
import { useState } from "react";
import { Button } from "@aevryn/ui/components/ui/button";
import MenuItem from "@aevryn/ui/components/ui/menu-item";
import { InputGroup, InputField } from "@aevryn/ui/components/ui/input-group";
import { getBrowserSupabase } from "@aevryn/auth";
import { useRouter } from "next/navigation";
import { useEffect } from "react";

type ThreadItem = {
  id: string;
  title: string;
  groupId: string | null;
  boundWorkflowId: string | null;
};

type GroupedItem = {
  id: string;
  title: string;
  idx: number;
};

type ThreadGroup = {
  label: string;
  items: GroupedItem[];
};

export function Header({
  workspaceId,
  threadId,
}: {
  workspaceId: string;
  threadId?: string;
}) {
  const router = useRouter();

  const supabase = getBrowserSupabase();

  const [query, setQuery] = useState<string>("");
  const [threads, setThreads] = useState<ThreadItem[]>([]);
  // Editorial state for the rename input. null = reflect the live thread
  // title; a string = the user is typing a rename.
  const [draftTitle, setDraftTitle] = useState<string | null>(null);

  useEffect(() => {
    async function fetchThreads() {
      const { data, error } = await supabase
        .from("threads")
        .select(
          `
          id,
          title,
          group_id,
          bound_workflow_id
        `,
        )
        .eq("workspace_id", workspaceId);

      if (!error && data) {
        setThreads(
          data.map((t: any) => ({
            id: t.id,
            title: t.title || "Untitled",
            groupId: t.group_id ?? null,
            boundWorkflowId: t.bound_workflow_id ?? null,
          })),
        );
      }
    }
    fetchThreads();

    const channel = supabase
      .channel(`threads:${workspaceId}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "threads",
          filter: `workspace_id=eq.${workspaceId}`,
        },
        (payload: any) => {
          setThreads((prev) => {
            const byId = new Map(prev.map((t) => [t.id, t]));

            if (payload.eventType === "DELETE") {
              byId.delete(payload.old.id);
            } else {
              const next: ThreadItem = {
                id: payload.new.id,
                title: payload.new.title || "Untitled",
                groupId: (payload.new.group_id as string | null) ?? null,
                boundWorkflowId:
                  (payload.new.bound_workflow_id as string | null) ?? null,
              };
              byId.set(payload.new.id, next);
            }

            return Array.from(byId.values());
          });
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [workspaceId, supabase]);

  // Reset the rename draft whenever the open thread changes.
  useEffect(() => {
    setDraftTitle(null);
  }, [threadId]);

  // Derive the active thread live instead of snapshotting its label — realtime
  // renames flow through this instantly, and the dropdown never goes stale.
  const activeThread = threadId
    ? threads.find((t) => t.id === threadId)
    : undefined;
  const activeLabel =
    activeThread && draftTitle !== null
      ? draftTitle
      : activeThread?.title;

  const commitRename = async () => {
    if (!activeThread || draftTitle === null) return;
    const next = draftTitle.trim();
    setDraftTitle(null);
    if (!next || next === activeThread.title) return;

    const { error } = await supabase
      .from("threads")
      .update({ title: next })
      .eq("id", activeThread.id);
    if (!error) {
      setThreads((prev) =>
        prev.map((t) =>
          t.id === activeThread.id ? { ...t, title: next } : t,
        ),
      );
    }
  };

  const groupedThreads = ((): ThreadGroup[] => {
    const filtered = query
      ? threads.filter((t) =>
          t.title.toLowerCase().includes(query.toLowerCase()),
        )
      : threads;

    const map = new Map<string, ThreadGroup>();
    let idx = 0;

    for (const t of filtered) {
      const key = t.groupId ?? "__ungrouped__";
      const existing = map.get(key);
      if (existing) {
        existing.items.push({ id: t.id, title: t.title, idx: idx++ });
      } else {
        map.set(key, {
          label: key === "__ungrouped__" ? "Other threads" : "Section",
          items: [{ id: t.id, title: t.title, idx: idx++ }],
        });
      }
    }

    return Array.from(map.values());
  })();

  return (
    <header className="flex h-12 shrink-0 items-center px-4">
      <div className="flex w-full min-w-0 flex-row items-center justify-between gap-2">
        <div className="flex flex-row items-center gap-px">
          <DropdownMenu>
            <DropdownTrigger
              render={
                <Button variant="ghost" trailingIcon={ChevronDown}>
                  {activeLabel || "Select a thread"}
                </Button>
              }
            />
            <DropdownContent checkedIndex={undefined}>
              <DropdownSearch
                value={query}
                onValueChange={setQuery}
                placeholder="Search threads"
              />
              {groupedThreads.map((group) => (
                <DropdownLabel key={group.label}>{group.label}</DropdownLabel>
              ))}
              {groupedThreads.flatMap((group) =>
                group.items.map((item) => (
                  <MenuItem
                    key={item.id}
                    index={item.idx}
                    label={item.title}
                    onSelect={() =>
                      router.push(`/workspace/${workspaceId}/${item.id}`)
                    }
                  ></MenuItem>
                )),
              )}
              {threads.length === 0 && (
                <DropdownEmpty>No threads found</DropdownEmpty>
              )}
            </DropdownContent>
          </DropdownMenu>
        </div>

        {/* Rename the open thread. Rendered whenever a thread is open — not
            gated on the thread list having loaded — so the field is always
            visible. */}
        {threadId ? (
          <div
            className="min-w-0 flex-1"
            onBlur={(e) => {
              if (!e.currentTarget.contains(e.relatedTarget)) commitRename();
            }}
          >
            <InputGroup className="mb-1">
              <InputField
                index={0}
                className="truncate"
                label="Thread name"
                labelHidden
                id="thread-name"
                placeholder="Thread name"
                value={draftTitle ?? activeThread?.title ?? ""}
                onChange={setDraftTitle}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.currentTarget.blur();
                  }
                }}
              />
            </InputGroup>
          </div>
        ) : null}
      </div>
    </header>
  );
}

